var n=`0066-gulyas`;var a=`world-0066`;var i=`HU`;var r=`eastern-europe`;var s=4;var o=92;var l={en:`Gulyás`,ua:`Гуляш`};var g={en:`A classic dish from Hungary, featuring beef chuck, yellow onion, carrot, red bell pepper. A practical home-kitchen version with measured step ingredients and clear cooking methods.`,ua:`Класична страва з Угорщина. Основні складники: яловича лопатка, жовта цибуля, морква, червоний солодкий перець. Домашній варіант із поетапними діями та точними кількостями продуктів.`};var u=[{en:`Pat the main ingredients dry. Brown in a hot heavy pan in batches for about 10 minutes, turning to color all sides.`,ua:`Обсушіть основні продукти. Обсмажуйте їх порціями на добре розігрітій важкій сковороді приблизно 10 хвилин, перевертаючи для рівної скоринки.`,t:[`searing`],m:10,i:[[`beef-chuck`,600,`g`],[`lard`,35,`g`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 10 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 10 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:10,i:[[`yellow-onion`,230,`g`],[`carrot`,160,`g`],[`red-bell-pepper`,140,`g`],[`sweet-paprika`,20,`g`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 70 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 70 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:70,i:[[`potato`,400,`g`],[`water`,1250,`ml`],[`tomato`,190,`g`],[`caraway-seeds`,4,`g`],[`bay-leaf`,1,`leaf`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[[`garlic`,3,`clove`],[`table-salt`,null,`to_taste`],[`ground-black-pepper`,null,`to_taste`]]}];var d={slug:n,id:a,country:`HU`,region:r,servings:4,minutes:92,title:l,text:g,steps:u};export{i as country,d as default,a as id,o as minutes,r as region,s as servings,n as slug,u as steps,g as text,l as title};